@import "@fontsource-variable/hanken-grotesk";

/* Light (faithful): #f1f1f1 page, #e6e6e6 bands (muted), white active cards, #242424 ink and
   filled buttons, #d9d9d9 icon buttons (secondary) with a #c7c7c7 hover (accent), #6d6d6d quiet
   labels, 25% ink hairlines. The blood red (#7d0b0d → #c23a33) only tints media placeholders. */
:root {
  --background: oklch(0.960 0 0);
  --foreground: oklch(0.254 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.254 0 0);
  --popover: oklch(0.960 0 0);
  --popover-foreground: oklch(0.254 0 0);
  --primary: oklch(0.254 0 0);
  --primary-foreground: oklch(0.960 0 0);
  --secondary: oklch(0.885 0 0);
  --secondary-foreground: oklch(0.254 0 0);
  --muted: oklch(0.925 0 0);
  --muted-foreground: oklch(0.530 0 0);
  --accent: oklch(0.835 0 0);
  --accent-foreground: oklch(0.254 0 0);
  --destructive: oklch(0.540 0.200 27);
  --destructive-foreground: oklch(0.985 0 0);
  --border: oklch(0.254 0 0 / 25%);
  --input: oklch(0.254 0 0 / 25%);
  --ring: oklch(0.530 0 0);
  --highlight: oklch(0.370 0.140 26);
  --highlight-foreground: oklch(0.960 0 0);
  --glow: oklch(0.580 0.170 27);
  --chart-1: oklch(0.254 0 0);
  --chart-2: oklch(0.530 0 0);
  --chart-3: oklch(0.370 0.140 26);
  --chart-4: oklch(0.580 0.170 27);
  --chart-5: oklch(0.835 0 0);
  --sidebar: oklch(0.925 0 0);
  --sidebar-foreground: oklch(0.254 0 0);
  --sidebar-primary: oklch(0.254 0 0);
  --sidebar-primary-foreground: oklch(0.960 0 0);
  --sidebar-accent: oklch(0.885 0 0);
  --sidebar-accent-foreground: oklch(0.254 0 0);
  --sidebar-border: oklch(0.254 0 0 / 25%);
  --sidebar-ring: oklch(0.530 0 0);

  --typeface-body: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.375rem;
  --page-width: 86rem;
  --page-gutter: 1rem;
  --section-y: 3.5rem;
}

@media (min-width: 64rem) {
  :root {
    --page-gutter: 2rem;
    --section-y: 6rem;
  }
}

/* Dark: the footer slab. #242424 page, #2e2e2e cards, #1c1c1c bands, #f1f1f1 ink and filled
   buttons, #3a3a3a icon buttons, white 10% hairlines; the reds stay. */
.dark {
  --background: oklch(0.254 0 0);
  --foreground: oklch(0.960 0 0);
  --card: oklch(0.295 0 0);
  --card-foreground: oklch(0.960 0 0);
  --popover: oklch(0.295 0 0);
  --popover-foreground: oklch(0.960 0 0);
  --primary: oklch(0.960 0 0);
  --primary-foreground: oklch(0.254 0 0);
  --secondary: oklch(0.345 0 0);
  --secondary-foreground: oklch(0.960 0 0);
  --muted: oklch(0.215 0 0);
  --muted-foreground: oklch(0.680 0 0);
  --accent: oklch(0.410 0 0);
  --accent-foreground: oklch(0.960 0 0);
  --destructive: oklch(0.650 0.190 25);
  --destructive-foreground: oklch(0.985 0 0);
  --border: oklch(1 0 0 / 10%);
  --input: oklch(1 0 0 / 15%);
  --ring: oklch(0.680 0 0);
  --highlight: oklch(0.370 0.140 26);
  --highlight-foreground: oklch(0.960 0 0);
  --glow: oklch(0.580 0.170 27);
  --chart-1: oklch(0.960 0 0);
  --chart-2: oklch(0.680 0 0);
  --chart-3: oklch(0.450 0.160 26);
  --chart-4: oklch(0.620 0.170 27);
  --chart-5: oklch(0.410 0 0);
  --sidebar: oklch(0.215 0 0);
  --sidebar-foreground: oklch(0.960 0 0);
  --sidebar-primary: oklch(0.960 0 0);
  --sidebar-primary-foreground: oklch(0.254 0 0);
  --sidebar-accent: oklch(0.345 0 0);
  --sidebar-accent-foreground: oklch(0.960 0 0);
  --sidebar-border: oklch(1 0 0 / 10%);
  --sidebar-ring: oklch(0.680 0 0);
}
